mapper.select:
SELECT a.*, e.name as employee_name, e.employee_no, e.entry_date, d.unit_name as dept_name, CASE WHEN d.unit_type = 2 THEN d.unit_name WHEN p1.unit_type = 2 THEN p1.unit_name WHEN p2.unit_type = 2 THEN p2.unit_name WHEN p3.unit_type = 2 THEN p3.unit_name ELSE NULL END as company_name, CASE WHEN fc.unit_name IS NOT NULL THEN fc.unit_name WHEN fd.unit_type = 2 THEN fd.unit_name WHEN fp1.unit_type = 2 THEN fp1.unit_name WHEN fp2.unit_type = 2 THEN fp2.unit_name WHEN fp3.unit_type = 2 THEN fp3.unit_name ELSE NULL END as from_company_name, CASE WHEN tc.unit_name IS NOT NULL THEN tc.unit_name WHEN td.unit_type = 2 THEN td.unit_name WHEN tp1.unit_type = 2 THEN tp1.unit_name WHEN tp2.unit_type = 2 THEN tp2.unit_name WHEN tp3.unit_type = 2 THEN tp3.unit_name ELSE NULL END as to_company_name, fd.unit_name as from_dept_name, td.unit_name as to_dept_name, h.name as handover_to_name FROM hr_application a LEFT JOIN hr_employee e ON a.employee_id = e.id LEFT JOIN org_unit d ON e.dept_id = d.id AND d.deleted = 0 LEFT JOIN org_unit p1 ON d.parent_id = p1.id AND p1.deleted = 0 LEFT JOIN org_unit p2 ON p1.parent_id = p2.id AND p2.deleted = 0 LEFT JOIN org_unit p3 ON p2.parent_id = p3.id AND p3.deleted = 0 LEFT JOIN org_unit fc ON a.from_company_id = fc.id AND fc.deleted = 0 LEFT JOIN org_unit tc ON a.to_company_id = tc.id AND tc.deleted = 0 LEFT JOIN org_unit fd ON a.from_dept_id = fd.id AND fd.deleted = 0 LEFT JOIN org_unit fp1 ON fd.parent_id = fp1.id AND fp1.deleted = 0 LEFT JOIN org_unit fp2 ON fp1.parent_id = fp2.id AND fp2.deleted = 0 LEFT JOIN org_unit fp3 ON fp2.parent_id = fp3.id AND fp3.deleted = 0 LEFT JOIN org_unit td ON a.to_dept_id = td.id AND td.deleted = 0 LEFT JOIN org_unit tp1 ON td.parent_id = tp1.id AND tp1.deleted = 0 LEFT JOIN org_unit tp2 ON tp1.parent_id = tp2.id AND tp2.deleted = 0 LEFT JOIN org_unit tp3 ON tp2.parent_id = tp3.id AND tp3.deleted = 0 LEFT JOIN hr_employee h ON a.handover_to = h.id WHERE a.deleted = 0
AND e.name LIKE CONCAT('%', #{employeeName}, '%')
AND e.employee_no LIKE CONCAT('%', #{employeeNo}, '%')
AND a.app_type = #{appType}
AND a.status = #{status}
AND a.employee_id = #{employeeId}
ORDER BY a.created_time DESC

SELECT a.*, e.name as employee_name, e.employee_no, e.entry_date, d.unit_name as dept_name, CASE WHEN d.unit_type = 2 THEN d.unit_name WHEN p1.unit_type = 2 THEN p1.unit_name WHEN p2.unit_type = 2 THEN p2.unit_name WHEN p3.unit_type = 2 THEN p3.unit_name ELSE NULL END as company_name, CASE WHEN fc.unit_name IS NOT NULL THEN fc.unit_name WHEN fd.unit_type = 2 THEN fd.unit_name WHEN fp1.unit_type = 2 THEN fp1.unit_name WHEN fp2.unit_type = 2 THEN fp2.unit_name WHEN fp3.unit_type = 2 THEN fp3.unit_name ELSE NULL END as from_company_name, CASE WHEN tc.unit_name IS NOT NULL THEN tc.unit_name WHEN td.unit_type = 2 THEN td.unit_name WHEN tp1.unit_type = 2 THEN tp1.unit_name WHEN tp2.unit_type = 2 THEN tp2.unit_name WHEN tp3.unit_type = 2 THEN tp3.unit_name ELSE NULL END as to_company_name, fd.unit_name as from_dept_name, td.unit_name as to_dept_name, h.name as handover_to_name FROM hr_application a LEFT JOIN hr_employee e ON a.employee_id = e.id LEFT JOIN org_unit d ON e.dept_id = d.id AND d.deleted = 0 LEFT JOIN org_unit p1 ON d.parent_id = p1.id AND p1.deleted = 0 LEFT JOIN org_unit p2 ON p1.parent_id = p2.id AND p2.deleted = 0 LEFT JOIN org_unit p3 ON p2.parent_id = p3.id AND p3.deleted = 0 LEFT JOIN org_unit fc ON a.from_company_id = fc.id AND fc.deleted = 0 LEFT JOIN org_unit tc ON a.to_company_id = tc.id AND tc.deleted = 0 LEFT JOIN org_unit fd ON a.from_dept_id = fd.id AND fd.deleted = 0 LEFT JOIN org_unit fp1 ON fd.parent_id = fp1.id AND fp1.deleted = 0 LEFT JOIN org_unit fp2 ON fp1.parent_id = fp2.id AND fp2.deleted = 0 LEFT JOIN org_unit fp3 ON fp2.parent_id = fp3.id AND fp3.deleted = 0 LEFT JOIN org_unit td ON a.to_dept_id = td.id AND td.deleted = 0 LEFT JOIN org_unit tp1 ON td.parent_id = tp1.id AND tp1.deleted = 0 LEFT JOIN org_unit tp2 ON tp1.parent_id = tp2.id AND tp2.deleted = 0 LEFT JOIN org_unit tp3 ON tp2.parent_id = tp3.id AND tp3.deleted = 0 LEFT JOIN hr_employee h ON a.handover_to = h.id WHERE a.deleted = 0 AND a.status = 0
AND e.name LIKE CONCAT('%', #{employeeName}, '%')
AND e.employee_no LIKE CONCAT('%', #{employeeNo}, '%')
AND a.app_type = #{appType}
AND EXISTS ( SELECT 1 FROM sys_approval_flow f JOIN sys_approval_node n ON f.id = n.flow_id AND n.deleted = 0 WHERE f.deleted = 0 AND f.status = 1 AND f.flow_type = a.app_type AND n.role_id IN
#{roleId}
)
AND 1 = 0
ORDER BY a.created_time DESC
